// Helper to construct normalized MCQ
function mcq(id, question, options, correctIndex, explanation, hint) {
  return {
    id,
    type: "mcq",
    question,
    options,
    correctIndex,
    explanation,
    hint
  };
}

// Helper to construct coding challenge
function code(id, title, statement, starter, hint, explanation) {
  return {
    id,
    type: "code",
    title,
    statement,
    starter,
    hint,
    explanation
  };
}

